"export interface Chapter {
  id: number;
  title: string;
  subtitle: string;
  summary: string;
  keyPoints: string[];
  details: {
    sectionTitle: string;
    content: string;
  }[];
}

export const chapters: Chapter[] = [
  {
    id: 1,
    title: "Chương 1: Cơ sở lý thuyết & Công nghệ",
    subtitle: "Nền tảng công nghệ và lý thuyết cốt lõi của EatFitAI",
    summary: "Trình bày về các nền tảng lý thuyết và công nghệ cốt lõi được áp dụng trong dự án EatFitAI, bao gồm React Native/Expo cho Mobile, ASP.NET Core cho Backend, Supabase cho Database/Auth/Storage, YOLO cho Computer Vision nhận diện món ăn, và Gemini API cho xử lý ngôn ngữ tự nhiên và phân tích dinh dưỡng.",
    keyPoints: [
      "Mobile App: React Native & Expo giúp xây dựng ứng dụng di động đa nền tảng hiệu quả.",
      "Backend: ASP.NET Core 9 Web API đảm nhận vai trò tập trung business logic, bảo mật và proxy.",
      "Database & Auth: Supabase (PostgreSQL 17) quản lý dữ liệu, kiểm soát truy cập Row-Level Security (RLS).",
      "Computer Vision: YOLOv11 ONNX model nhận diện món ăn từ hình ảnh camera người dùng chụp.",
      "Generative AI: Gemini API sinh thực đơn, phân tích món ăn chi tiết, phân rã công thức nấu ăn và phân tích giọng nói (Voice parse).",
      "Media Storage: Cloudflare R2 phục vụ lưu trữ file hình ảnh tĩnh giúp tối ưu hóa chi phí egress.",
      "Infrastructure: AWS Lightsail Singapore làm máy chủ chạy chính, Caddy làm Reverse Proxy kiêm HTTPS tự động."
    ],
    details: [
      {
        sectionTitle: "1.1 Tại sao sử dụng kiến trúc Backend làm Proxy?",
        content: "Ứng dụng di động không gọi trực tiếp các dịch vụ Supabase Service Role, AI Provider hay Gemini API. Mọi yêu cầu đều phải đi qua lớp Backend API trung gian. Điều n
