"export interface Flashcard {
  id: number;
  question: string;
  answer: string;
  category: string;
}

export const flashcards: Flashcard[] = [
  {
    id: 1,
    question: "Tại sao không cho Mobile App gọi trực tiếp dịch vụ Supabase/Gemini API?",
    answer: "Để bảo mật và quản lý tập trung. Nếu gọi trực tiếp, các API Keys nhạy cảm (như Gemini Key, Supabase Service Role Key) sẽ bị nhúng trong mã nguồn ứng dụng di động, hacker có thể dịch ngược (decompile) APK để lấy cắp. Qua Backend API làm proxy, các keys này chỉ lưu an toàn trên server.",
    category: "Kiến Trúc & Bảo Mật"
  },
  {
    id: 2,
    question: "Row Level Security (RLS) trong Supabase hoạt động như thế nào?",
    answer: "RLS là cơ chế bảo mật ở mức hàng trong PostgreSQL. Khi bật RLS, mỗi truy vấn SQL đọc/ghi từ client đều phải đi qua các chính sách (policies) kiểm tra quyền truy cập. Ví dụ, người dùng chỉ được đọc/ghi dòng dữ liệu có cột `user_id` trùng với ID tài khoản của họ (`auth.uid()`).",
    category: "Bảo Mật Cơ Sở Dữ Liệu"
  },
  {
    id: 3,
    question: "Cảnh báo 'RLS enabled no policy' của Database Advisor nghĩa là gì?",
    answer: "Nghĩa là bảng đó đã bật tính năng Row Level Security nhưng chưa có chính sách (policy) nào được tạo. Theo cơ chế mặc định của Postgres, khi bật RLS mà không có policy, mọi quyền truy cập (SELECT/INSERT/UPDATE/DELETE) từ các tài khoản client thông thường đều bị từ chối tuyệt đối. Việc này an toàn nếu bảng đó chỉ dành cho backend/admin sử dụng service role.",
    category: "Bảo Mật Cơ Sở Dữ Liệu"
  },
  {
    id: 4,
    question: "Cơ chế 'Auto-Discovery' trong môi trường local hoạt động như thế nào?",
    answer: "Khi chạy local dev, mobile app tự động l
