"export interface QuizQuestion {
  id: number;
  question: string;
  options: string[];
  correctAnswer: number; // Index (0-3)
  explanation: string;
}

export const quizzes: QuizQuestion[] = [
  {
    id: 1,
    question: "Tại sao ứng dụng di động EatFitAI không gọi trực tiếp Supabase Data API mà phải đi qua Backend ASP.NET Core?",
    options: [
      "Vì React Native không hỗ trợ kết nối trực tiếp với PostgreSQL/Supabase.",
      "Để tập trung business logic, áp dụng rate limiting, phân quyền phức tạp và tránh lộ bí mật (secrets/API keys) trên client.",
      "Vì gọi trực tiếp qua Supabase sẽ làm tăng độ trễ mạng lên gấp hai lần.",
      "Để ứng dụng chạy offline tốt hơn mà không cần kết nối internet."
    ],
    correctAnswer: 1,
    explanation: "Đây là quyết định kiến trúc cốt lõi. Gọi trực tiếp Supabase từ mobile bắt buộc phải nhúng API keys hoặc cấp quyền trực tiếp cho client, rất dễ bị dịch ngược ứng dụng lấy cắp. Đi qua Backend giúp che giấu cấu trúc database, quản lý tập trung mã khóa (secrets) và dễ áp dụng rate limiting, logging."
  },
  {
    id: 2,
    question: "Cơ chế phân quyền Row Level Security (RLS) bảo vệ dữ liệu ở mức nào trong hệ quản trị cơ sở dữ liệu?",
    options: [
