"import React, { useState } from "react";
import Dashboard from "./views/Dashboard";
import Learn from "./views/Learn";
import Flashcard from "./views/Flashcard";
import Quiz from "./views/Quiz";
import ChatDefense from "./views/ChatDefense";
import RubricView from "./views/RubricView";
import { LayoutDashboard, BookOpen, CreditCard, Award, MessageSquare, ClipboardList, Menu, X } from "lucide-react";

type View = "dashboard" | "learn" | "flashcards" | "quiz" | "chat" | "rubric";

function App() {
  const [currentView, setCurrentView] = useState<View>("dashboard");
  const [sidebarOpen, setSidebarOpen] = useState<boolean>(false);

  const renderView = () => {
    switch (currentView) {
      case "dashboard":
        return <Dashboard onNavigate={(view) => setCurrentView(view as View)} />;
      case "learn":
        return <Learn />;
      case "flashcards":
        return <Flashcard />;
      case "quiz":
        return <Quiz />;
      case "chat":
        return <ChatDefense />;
      case "rubric":
        return <RubricView />;
      default:
        return <Dashboard onNavigate={(view) => setCurrentView(view as View)} />;
    }
  };

