    if (activeChapterId === 1) setSelectedNode("ImageResize");
    else if (activeChapterId === 2) setSelectedNode("UserGroup");
    else if (activeChapterId === 3) setSelectedNode("Backend");
    else if (activeChapterId === 4) setSelectedNode("UnitTests");
  }, [activeChapterId]);

