"import React, { useState } from "react";
import { 
  Award, 
  HelpCircle, 
  Lightbulb, 
  BookOpen, 
  Code, 
  Cloud, 
  ShieldCheck, 
  X, 
  ExternalLink,
  ChevronRight
} from "lucide-react";

// Định nghĩa cấu trúc link liên kết
interface KnowledgeLink {
  label: string;
  path: string;
}

// Định nghĩa kiểu dữ liệu cho một node kiến thức dạng hình hộp
interface KnowledgeNode {
  id: string;
  label: string;
  subLabel: string;
  category: "center" | "nutrition" | "code" | "infra" | "security";
  level: 0 | 1 | 2 | 3;
  parentId?: string; // ID của node cha
  x: number;
  y: number;
  w: number;
  h: number;
  summary: string;
  links: KnowledgeLink[];
  qaList: {
    question: string;
    answer: string;
  }[];
}

// Định nghĩa kiểu dữ liệu cho đường nối
interface KnowledgeEdge {
  from: string;
  to: string;
  category: "nutrition" | "code" | "infra" | "security";
  level: 1 | 2 | 3; // Cấp liên kết: 1: Center->L1, 2: L1->L2, 3: L2->L3
}

