  // Mặc định: Dinh dưỡng (Level 1) mở, các nhóm con của Dinh dưỡng mở. Các nhánh khác đóng.
  const [expanded, setExpanded] = useState<Record<string, boolean>>({
    // Level 1 Branches
    nutrition: true,
    code: false,
    infra: false,
    security: false,

    // Level 2 Sub-groups
    "nutrition-calc": true,
    "nutrition-inputs": true,
    "code-structure": false,
    "code-integration": false,
    "infra-server": false,
    "infra-storage": false,
    "security-data": false,
    "security-ops": false
  });

