"export default function KnowledgeMap({ highlightNodeId, onClearHighlight }: KnowledgeMapProps) {
  const [selectedNodeId, setSelectedNodeId] = useState<string>("center");
  const [isModalOpen, setIsModalOpen] = useState<boolean>(false);
  const [modalTab, setModalTab] = useState<"theory" | "git" | "source">("theory");

  // State quản lý việc xem mã nguồn đính kèm
  const [selectedCodeKey, setSelectedCodeKey] = useState<string | null>(null);
  const [isCodeViewerOpen, setIsCodeViewerOpen] = useState<boolean>(false);

  useEffect(() => {
    if (highlightNodeId) {
      const targetNode = nodes.find(n => n.id === highlightNodeId);
      if (targetNode) {
        setSelectedNodeId(highlightNodeId);
        setModalTab("theory");
        setIsModalOpen(true);

        // Tự động bung các nhánh cha liên quan
        setExpanded(prev => {
          const next = { ...prev };
          if (targetNode.category && targetNode.category !== "center") {
            next[targetNode.category] = true;
          }
          if (targetNode.parentId) {
            next[targetNode.parentId] = true;
          }
          return next;
        });
      }

      if (onClearHighlight) {
        onClearHighlight();
      }
    }
  }, [highlightNodeId]);
"

