"  // Gắn sự kiện Wheel (con lăn chuột) để thực hiện Zoom to Cursor (Zoom đa chiều mượt mà)
  useEffect(() => {
    const svgEl = svgRef.current;
    if (!svgEl) return;

    const handleWheelEvent = (e: WheelEvent) => {
      e.preventDefault(); // Ngăn cuộn trang web mặc định

      const rect = svgEl.getBoundingClientRect();
      const mouseX = e.clientX - rect.left;
      const mouseY = e.clientY - rect.top;

      const zoomIntensity = 0.05;
      const direction = e.deltaY < 0 ? 1 : -1;

      setZoom((prevZoom) => {
        const nextZoom = Math.min(1.8, Math.max(0.3, prevZoom + direction * zoomIntensity));

        // Điều chỉnh pan để giữ nguyên điểm dưới con trỏ chuột trước và sau khi zoom
        setPan((prevPan) => {
          const newPanX = mouseX - ((mouseX - prevPan.x) / prevZoom) * nextZoom;
          const newPanY = mouseY - ((mouseY - prevPan.y) / prevZoom) * nextZoom;
          return { x: newPanX, y: newPanY };
        });

        return nextZoom;
      });
    };

    svgEl.addEventListener("wheel", handleWheelEvent, { passive: false });
    return () => {
      svgEl.removeEventListener("wheel", handleWheelEvent);
    };
  }, []);"

